INSERT INTO page_content (key,label,page,section,type,value_en,value_bs,sort_order,font_size,font_family,text_color) VALUES ('home.intro.title.part1','Naslov: dio 1','home','intro','text','Fine-art,','Fine-art,',1,NULL,NULL,NULL) ON CONFLICT (key) DO NOTHING;
INSERT INTO page_content (key,label,page,section,type,value_en,value_bs,sort_order,font_size,font_family,text_color) VALUES ('home.intro.title.part2','Naslov: dio 2 (kurziv)','home','intro','text','Editorial','Editorijalna',2,NULL,NULL,NULL) ON CONFLICT (key) DO NOTHING;
INSERT INTO page_content (key,label,page,section,type,value_en,value_bs,sort_order,font_size,font_family,text_color) VALUES ('home.intro.title.part3','Naslov: dio 3','home','intro','text','Wedding Photography','Vjenčana Fotografija',3,NULL,NULL,NULL) ON CONFLICT (key) DO NOTHING;
INSERT INTO page_content (key,label,page,section,type,value_en,value_bs,sort_order,font_size,font_family,text_color) VALUES ('home.intro.desc','Opis','home','intro','textarea','Our approach is rooted in the belief that every wedding is a unique masterpiece. We blend editorial sophistication with documentary honesty to capture the quiet grandeur and fleeting magic of your most significant day.','Naš pristup temelji se na uvjerenju da je svako vjenčanje jedinstveno remek-djelo. Spajamo editorijalnu sofisticiranost s dokumentarnom iskrenošću kako bismo zabilježili tihu raskoš i prolaznu magiju vašeg najznačajnijeg dana.',4,NULL,NULL,NULL) ON CONFLICT (key) DO NOTHING;
INSERT INTO page_content (key,label,page,section,type,value_en,value_bs,sort_order,font_size,font_family,text_color) VALUES ('home.process.01.title','Korak 1: Naslov','home','process','text','We begin with your vision','Počinjemo s vašom vizijom',0,NULL,NULL,NULL) ON CONFLICT (key) DO NOTHING;
INSERT INTO page_content (key,label,page,section,type,value_en,value_bs,sort_order,font_size,font_family,text_color) VALUES ('home.process.01.tag','Korak 1: Tag','home','process','text','And our artistic style','I našim umjetničkim stilom',1,NULL,NULL,NULL) ON CONFLICT (key) DO NOTHING;
INSERT INTO page_content (key,label,page,section,type,value_en,value_bs,sort_order,font_size,font_family,text_color) VALUES ('home.process.01.desc','Korak 1: Opis','home','process','textarea','If you have ideas or specific requests, please let us know. The pre-wedding shoot is a big collaboration — whilst we are happy to direct, we also love working with couples to create truly remarkable images.','Ako imate ideje ili specifične zahtjeve, slobodno nam javite. Fotografisanje prije vjenčanja je velika saradnja — rado usmjeravamo, ali volimo i raditi s parovima na stvaranju izvanrednih slika.',2,NULL,NULL,NULL) ON CONFLICT (key) DO NOTHING;
INSERT INTO page_content (key,label,page,section,type,value_en,value_bs,sort_order,font_size,font_family,text_color) VALUES ('home.process.02.title','Korak 2: Naslov','home','process','text','You choose the location','Vi birate lokaciju',3,NULL,NULL,NULL) ON CONFLICT (key) DO NOTHING;
INSERT INTO page_content (key,label,page,section,type,value_en,value_bs,sort_order,font_size,font_family,text_color) VALUES ('home.process.02.tag','Korak 2: Tag','home','process','text','We document the moments','Mi dokumentujemo trenutke',4,NULL,NULL,NULL) ON CONFLICT (key) DO NOTHING;
INSERT INTO page_content (key,label,page,section,type,value_en,value_bs,sort_order,font_size,font_family,text_color) VALUES ('home.process.02.desc','Korak 2: Opis','home','process','textarea','Often it''s possible to shoot in the city and the countryside to get beautiful variation. We handle all logistics and transport, so you can focus entirely on being present.','Često je moguće obaviti fotografisanje u gradu i na selu kako bismo dobili lijepu varijaciju. Brinemo o svoj logistici i prevozu kako biste se mogli potpuno posvetiti trenutku.',5,NULL,NULL,NULL) ON CONFLICT (key) DO NOTHING;
INSERT INTO page_content (key,label,page,section,type,value_en,value_bs,sort_order,font_size,font_family,text_color) VALUES ('home.process.03.title','Korak 3: Naslov','home','process','text','We create art that lasts a lifetime','Zajedno stvaramo umjetnost koja traje vječno',6,NULL,NULL,NULL) ON CONFLICT (key) DO NOTHING;
INSERT INTO page_content (key,label,page,section,type,value_en,value_bs,sort_order,font_size,font_family,text_color) VALUES ('home.process.03.tag','Korak 3: Tag','home','process','text','Heirloom images for generations','Naslijedne slike za generacije',7,NULL,NULL,NULL) ON CONFLICT (key) DO NOTHING;
INSERT INTO page_content (key,label,page,section,type,value_en,value_bs,sort_order,font_size,font_family,text_color) VALUES ('home.process.03.desc','Korak 3: Opis','home','process','textarea','Our shoots are relaxed and filled with laughter — there are never any stiff poses. Just beautiful, natural moments and genuine connection. We often explore different locations and many couples choose to bring a change of outfit.','Naša fotografisanja su opuštena i puna smijeha — nikada nema ukočenih poza. Samo lijepi, prirodni trenuci i iskrena veza. Često istražujemo različite lokacije, a mnogi parovi biraju i promjenu odjeće.',8,NULL,NULL,NULL) ON CONFLICT (key) DO NOTHING;
INSERT INTO page_content (key,label,page,section,type,value_en,value_bs,sort_order,font_size,font_family,text_color) VALUES ('home.process.03.cta','Korak 3: CTA gumb','home','process','text','Let''s Connect','Povežimo se',9,NULL,NULL,NULL) ON CONFLICT (key) DO NOTHING;
