INSERT INTO page_content (key,label,page,section,type,value_en,value_bs,sort_order,font_size,font_family,text_color) VALUES ('about.hero.subtitle','Hero: Podnaslov','about','hero','text','The Artists Behind the Lens','Umjetnici iza objektiva',1,NULL,NULL,NULL) ON CONFLICT (key) DO NOTHING;
