INSERT INTO page_content (key,label,page,section,type,value_en,value_bs,sort_order,font_size,font_family,text_color) VALUES ('experience.intro.tag','Uvod: Tag','services','intro','text','The Experience','Iskustvo',0,NULL,NULL,NULL) ON CONFLICT (key) DO NOTHING;
INSERT INTO page_content (key,label,page,section,type,value_en,value_bs,sort_order,font_size,font_family,text_color) VALUES ('experience.intro.title.part1','Uvod: Naslov dio 1','services','intro','text','More than just','Više od',1,NULL,NULL,NULL) ON CONFLICT (key) DO NOTHING;
INSERT INTO page_content (key,label,page,section,type,value_en,value_bs,sort_order,font_size,font_family,text_color) VALUES ('experience.intro.title.part2','Uvod: Naslov dio 2 (kurziv)','services','intro','text','vendors.','dobavljača.',2,NULL,NULL,NULL) ON CONFLICT (key) DO NOTHING;
INSERT INTO page_content (key,label,page,section,type,value_en,value_bs,sort_order,font_size,font_family,text_color) VALUES ('experience.intro.desc','Uvod: Opis','services','intro','textarea','When you hire us, you aren''t just getting "vendors." You are getting a team that works as one. We''ve spent years refining our silent language, knowing exactly where the other is and what they are seeing.','Kada nas angažujete, ne dobijate samo "dobavljače". Dobijate tim koji radi kao jedno. Proveli smo godine usavršavajući naš tihi jezik, znajući tačno gdje je drugi i što vidi.',3,NULL,NULL,NULL) ON CONFLICT (key) DO NOTHING;
INSERT INTO page_content (key,label,page,section,type,value_en,value_bs,sort_order,font_size,font_family,text_color) VALUES ('experience.benefit.tag','Korist: Tag','services','philosophy','text','The Benefit','Korist',0,NULL,NULL,NULL) ON CONFLICT (key) DO NOTHING;
INSERT INTO page_content (key,label,page,section,type,value_en,value_bs,sort_order,font_size,font_family,text_color) VALUES ('experience.benefit.desc','Korist: Opis','services','philosophy','textarea','While one of us focuses on the grand, epic "hero" shot, the other is hunting for the quiet, emotional detail — the way your hand shakes, the tear your father wipes away, or the wild energy on the dance floor.','Dok se jedan od nas fokusira na veliki, epski kadar, drugi traži tihi, emocionalni detalj — način na koji vam ruka drhti, suzu koju vaš otac briše ili divlju energiju na plesnom podiju.',1,NULL,NULL,NULL) ON CONFLICT (key) DO NOTHING;
INSERT INTO page_content (key,label,page,section,type,value_en,value_bs,sort_order,font_size,font_family,text_color) VALUES ('experience.result.tag','Rezultat: Tag','services','philosophy','text','The Result','Rezultat',2,NULL,NULL,NULL) ON CONFLICT (key) DO NOTHING;
INSERT INTO page_content (key,label,page,section,type,value_en,value_bs,sort_order,font_size,font_family,text_color) VALUES ('about.experience.title','Iskustvo: Naslov','about','experience','text','How We Work','Kako Radimo',1,NULL,NULL,NULL) ON CONFLICT (key) DO NOTHING;
INSERT INTO page_content (key,label,page,section,type,value_en,value_bs,sort_order,font_size,font_family,text_color) VALUES ('experience.result.desc','Rezultat: Opis','services','philosophy','textarea','Your photos and your film will feel like they belong together. The same colors, the same mood, and the same soul. A cohesive visual legacy that tells your story from every angle.','Vaše fotografije i vaš film će izgledati kao da idu zajedno. Iste boje, isto raspoloženje i ista duša. Kohezivno vizualno naslijeđe koje priča vašu priču iz svakog kuta.',3,NULL,NULL,NULL) ON CONFLICT (key) DO NOTHING;
INSERT INTO page_content (key,label,page,section,type,value_en,value_bs,sort_order,font_size,font_family,text_color) VALUES ('experience.philosophy','Filozofija: Citat','services','philosophy','textarea','"We believe that the most powerful images aren''t staged; they are felt."','"Vjerujemo da najmoćnije slike nisu postavljene; one se osjećaju."',4,NULL,NULL,NULL) ON CONFLICT (key) DO NOTHING;
INSERT INTO page_content (key,label,page,section,type,value_en,value_bs,sort_order,font_size,font_family,text_color) VALUES ('experience.investment.tag','Investicija: Tag','services','investment','text','Investment','Investicija',0,NULL,NULL,NULL) ON CONFLICT (key) DO NOTHING;
INSERT INTO page_content (key,label,page,section,type,value_en,value_bs,sort_order,font_size,font_family,text_color) VALUES ('experience.investment.title','Investicija: Naslov','services','investment','text','Curated Collections','Odabrane Kolekcije',1,NULL,NULL,NULL) ON CONFLICT (key) DO NOTHING;
INSERT INTO page_content (key,label,page,section,type,value_en,value_bs,sort_order,font_size,font_family,text_color) VALUES ('experience.investment.availability','Dostupnost (obavijest)','services','investment','text','Limited Availability for 2026 Weddings','Ograničena dostupnost za vjenčanja 2026.',2,NULL,NULL,NULL) ON CONFLICT (key) DO NOTHING;
INSERT INTO page_content (key,label,page,section,type,value_en,value_bs,sort_order,font_size,font_family,text_color) VALUES ('experience.faq.1.q','Pitanje 1','services','faq','text','How would you describe your artistic approach on the wedding day?','Kako biste opisali vaš artistički pristup na dan vjenčanja?',0,NULL,NULL,NULL) ON CONFLICT (key) DO NOTHING;
INSERT INTO page_content (key,label,page,section,type,value_en,value_bs,sort_order,font_size,font_family,text_color) VALUES ('experience.faq.1.a','Odgovor 1','services','faq','textarea','We describe our style as cinematic and editorial. We find the perfect balance between being discreet observers — capturing those raw, unscripted emotions — and providing intentional, high-end direction during portraits. Our goal is to make you feel like yourselves, never like you are performing for the camera.','Naš stil opisujemo kao kinematski i editorijalni. Nalazimo savršenu ravnotežu između diskretnih promatrača i pružanja namjerne, vrhunske direkcije tokom portreta. Naš cilj je da se osjećate kao vi sami.',1,NULL,NULL,NULL) ON CONFLICT (key) DO NOTHING;
INSERT INTO page_content (key,label,page,section,type,value_en,value_bs,sort_order,font_size,font_family,text_color) VALUES ('experience.faq.2.q','Pitanje 2','services','faq','text','How many artists will be present at our wedding?','Koliko umjetnika će biti prisutno na našem vjenčanju?',2,NULL,NULL,NULL) ON CONFLICT (key) DO NOTHING;
INSERT INTO page_content (key,label,page,section,type,value_en,value_bs,sort_order,font_size,font_family,text_color) VALUES ('experience.faq.2.a','Odgovor 2','services','faq','textarea','You will always have two dedicated artists with you. As a husband-and-wife team, we move in unison to ensure no moment is missed. This dual perspective allows us to capture the grand architecture of the ceremony while simultaneously focusing on the quiet, whispered details and guest reactions.','Uvijek ćete imati dva posvećena umjetnika uz vas. Kao tim muža i žene, krećemo se unisono kako bismo osigurali da nijedan trenutak ne bude propušten.',3,NULL,NULL,NULL) ON CONFLICT (key) DO NOTHING;
INSERT INTO page_content (key,label,page,section,type,value_en,value_bs,sort_order,font_size,font_family,text_color) VALUES ('experience.faq.3.q','Pitanje 3','services','faq','text','When can we expect to see our final wedding gallery?','Kada možemo očekivati finalnu galeriju vjenčanja?',4,NULL,NULL,NULL) ON CONFLICT (key) DO NOTHING;
INSERT INTO page_content (key,label,page,section,type,value_en,value_bs,sort_order,font_size,font_family,text_color) VALUES ('experience.faq.3.a','Odgovor 3','services','faq','textarea','Quality and artistry take time, but we know you are eager to relive the magic. You will receive a curated "sneak peek" collection within 48 hours of your wedding. Your complete portfolio will be delivered in approximately 6 to 8 weeks.','Kvaliteta i umjetnost zahtijevaju vrijeme. U roku od 48 sati primit ćete "sneak peek" kolekciju, a kompletni portfolio za otprilike 6 do 8 sedmica.',5,NULL,NULL,NULL) ON CONFLICT (key) DO NOTHING;
INSERT INTO page_content (key,label,page,section,type,value_en,value_bs,sort_order,font_size,font_family,text_color) VALUES ('experience.faq.4.q','Pitanje 4','services','faq','text','Do you offer travel for destination weddings?','Nudite li putovanje za destinacijska vjenčanja?',6,NULL,NULL,NULL) ON CONFLICT (key) DO NOTHING;
INSERT INTO page_content (key,label,page,section,type,value_en,value_bs,sort_order,font_size,font_family,text_color) VALUES ('experience.faq.4.a','Odgovor 4','services','faq','textarea','Absolutely. We are driven by unique stories and beautiful landscapes, and we are available for travel worldwide. We handle all our own travel logistics to ensure a seamless experience for you.','Apsolutno. Pokreću nas jedinstvene priče i lijepi krajolici, dostupni smo za putovanje širom svijeta i brinemo o svim putnim logistikama.',7,NULL,NULL,NULL) ON CONFLICT (key) DO NOTHING;
INSERT INTO page_content (key,label,page,section,type,value_en,value_bs,sort_order,font_size,font_family,text_color) VALUES ('portfolio.approach.heading','Pristup: Naslov','portfolio','approach','text','Preserving every','Čuvamo svako',1,NULL,NULL,NULL) ON CONFLICT (key) DO NOTHING;
