INSERT INTO page_content (key,label,page,section,type,value_en,value_bs,sort_order,font_size,font_family,text_color) VALUES ('home.testimonials.tag','Testimonials: Tag','home','testimonials','text','Kind Words','Lijepe Riječi',0,NULL,NULL,NULL) ON CONFLICT (key) DO NOTHING;
INSERT INTO page_content (key,label,page,section,type,value_en,value_bs,sort_order,font_size,font_family,text_color) VALUES ('home.testimonials.title','Testimonials: Naslov','home','testimonials','text','From Our Couples','Od Naših Parova',1,NULL,NULL,NULL) ON CONFLICT (key) DO NOTHING;
INSERT INTO page_content (key,label,page,section,type,value_en,value_bs,sort_order,font_size,font_family,text_color) VALUES ('home.fallback.quote','Fallback citat','home','testimonials','textarea','Every couple has a rhythm; every wedding has a pulse. Our mission is to find the quiet, cinematic moments that define your unique narrative.','Svaki par ima ritam; svako vjenčanje ima puls. Naša misija je pronaći tihe, kinematske trenutke koji definišu vaš jedinstveni narativ.',2,NULL,NULL,NULL) ON CONFLICT (key) DO NOTHING;
