INSERT INTO page_content (key,label,page,section,type,value_en,value_bs,sort_order,font_size,font_family,text_color) VALUES ('about.step.1.title','Korak 1: Naslov','about','experience','text','Consultation & Planning','Konsultacije i planiranje',2,NULL,NULL,NULL) ON CONFLICT (key) DO NOTHING;
INSERT INTO page_content (key,label,page,section,type,value_en,value_bs,sort_order,font_size,font_family,text_color) VALUES ('about.step.1.desc','Korak 1: Opis','about','experience','textarea','We begin with a conversation to align our vision. Together, we''ll plan the story, location, and scenography to ensure every detail is intentional.','Počinjemo razgovorom kako bismo uskladili našu viziju. Zajedno ćemo planirati priču, lokaciju i scenografiju kako bismo osigurali da svaki detalj bude namjeran.',3,NULL,NULL,NULL) ON CONFLICT (key) DO NOTHING;
INSERT INTO page_content (key,label,page,section,type,value_en,value_bs,sort_order,font_size,font_family,text_color) VALUES ('about.step.2.title','Korak 2: Naslov','about','experience','text','Preparation & Guidance','Priprema i vođenje',4,NULL,NULL,NULL) ON CONFLICT (key) DO NOTHING;
INSERT INTO page_content (key,label,page,section,type,value_en,value_bs,sort_order,font_size,font_family,text_color) VALUES ('about.step.2.desc','Korak 2: Opis','about','experience','textarea','Receive a curated guide on posing and styling. We provide the advice you need to feel relaxed, confident, and ready for the camera.','Dobijte kurirani vodič o poziranju i stilizovanju. Pružamo savjete koji su vam potrebni da se osjećate opušteno, samouvjereno i spremno za kameru.',5,NULL,NULL,NULL) ON CONFLICT (key) DO NOTHING;
INSERT INTO page_content (key,label,page,section,type,value_en,value_bs,sort_order,font_size,font_family,text_color) VALUES ('about.step.3.title','Korak 3: Naslov','about','experience','text','The Shoot & Experience','Snimanje i iskustvo',6,NULL,NULL,NULL) ON CONFLICT (key) DO NOTHING;
INSERT INTO page_content (key,label,page,section,type,value_en,value_bs,sort_order,font_size,font_family,text_color) VALUES ('about.step.3.desc','Korak 3: Opis','about','experience','textarea','On the day of the shoot, we bring the magic to life. We handle the logistics — including transportation to the location — so you can focus entirely on the moment.','Na dan snimanja, oživljavamo magiju. Mi brinemo o logistici — uključujući prevoz do lokacije — tako da se možete u potpunosti fokusirati na trenutak.',7,NULL,NULL,NULL) ON CONFLICT (key) DO NOTHING;
INSERT INTO page_content (key,label,page,section,type,value_en,value_bs,sort_order,font_size,font_family,text_color) VALUES ('about.step.4.title','Korak 4: Naslov','about','experience','text','Post-Production','Postprodukcija',8,NULL,NULL,NULL) ON CONFLICT (key) DO NOTHING;
INSERT INTO page_content (key,label,page,section,type,value_en,value_bs,sort_order,font_size,font_family,text_color) VALUES ('about.step.4.desc','Korak 4: Opis','about','experience','textarea','Every chosen frame undergoes a meticulous editing process to ensure a timeless aesthetic. Your final gallery is delivered via a private digital space.','Svaki odabrani kadar prolazi kroz pedantan proces uređivanja kako bi se osigurala bezvremenska estetika. Vaša finalna galerija se dostavlja putem privatnog digitalnog prostora.',9,NULL,NULL,NULL) ON CONFLICT (key) DO NOTHING;
