INSERT INTO page_content (key,label,page,section,type,value_en,value_bs,sort_order,font_size,font_family,text_color) VALUES ('experience.journey.step.1.title','Korak 1: Naslov','services','journey','text','Consultation & Planning','Konsultacije i planiranje',2,NULL,NULL,NULL) ON CONFLICT (key) DO NOTHING;
INSERT INTO page_content (key,label,page,section,type,value_en,value_bs,sort_order,font_size,font_family,text_color) VALUES ('experience.journey.step.1.desc','Korak 1: Opis','services','journey','textarea','We begin with a conversation to align our vision. Together, we''ll plan the story, location, and scenography to ensure every detail is intentional.','Počinjemo razgovorom kako bismo uskladili našu viziju.',3,NULL,NULL,NULL) ON CONFLICT (key) DO NOTHING;
INSERT INTO page_content (key,label,page,section,type,value_en,value_bs,sort_order,font_size,font_family,text_color) VALUES ('experience.journey.step.2.title','Korak 2: Naslov','services','journey','text','Preparation & Guidance','Priprema i vođenje',4,NULL,NULL,NULL) ON CONFLICT (key) DO NOTHING;
INSERT INTO page_content (key,label,page,section,type,value_en,value_bs,sort_order,font_size,font_family,text_color) VALUES ('experience.journey.step.2.desc','Korak 2: Opis','services','journey','textarea','Receive a curated guide on posing and styling. We provide the advice you need to feel relaxed, confident, and ready for the camera.','Dobijte kurirani vodič o poziranju i stilizovanju.',5,NULL,NULL,NULL) ON CONFLICT (key) DO NOTHING;
INSERT INTO page_content (key,label,page,section,type,value_en,value_bs,sort_order,font_size,font_family,text_color) VALUES ('experience.journey.step.3.title','Korak 3: Naslov','services','journey','text','The Shoot & Experience','Snimanje i iskustvo',6,NULL,NULL,NULL) ON CONFLICT (key) DO NOTHING;
INSERT INTO page_content (key,label,page,section,type,value_en,value_bs,sort_order,font_size,font_family,text_color) VALUES ('experience.journey.step.3.desc','Korak 3: Opis','services','journey','textarea','On the day of the shoot, we bring the magic to life. We handle the logistics so you can focus entirely on the moment.','Na dan snimanja, oživljavamo magiju. Mi brinemo o logistici.',7,NULL,NULL,NULL) ON CONFLICT (key) DO NOTHING;
INSERT INTO page_content (key,label,page,section,type,value_en,value_bs,sort_order,font_size,font_family,text_color) VALUES ('experience.journey.step.4.title','Korak 4: Naslov','services','journey','text','Post-Production','Postprodukcija',8,NULL,NULL,NULL) ON CONFLICT (key) DO NOTHING;
INSERT INTO page_content (key,label,page,section,type,value_en,value_bs,sort_order,font_size,font_family,text_color) VALUES ('experience.journey.step.4.desc','Korak 4: Opis','services','journey','textarea','Every chosen frame undergoes a meticulous editing process to ensure a timeless aesthetic. Your final gallery is delivered via a private digital space.','Svaki odabrani kadar prolazi kroz pedantan proces uređivanja.',9,NULL,NULL,NULL) ON CONFLICT (key) DO NOTHING;
