INSERT INTO page_content (key,label,page,section,type,value_en,value_bs,sort_order,font_size,font_family,text_color) VALUES ('experience.addons.2.title','Addon 2: Naslov','services','addons','text','The Blueprint','Plan',2,NULL,NULL,NULL) ON CONFLICT (key) DO NOTHING;
INSERT INTO page_content (key,label,page,section,type,value_en,value_bs,sort_order,font_size,font_family,text_color) VALUES ('experience.addons.2.desc','Addon 2: Opis','services','addons','textarea','A pre-wedding creative consultation to discuss scenography, lighting, and the flow of your story.','Kreativna konsultacija prije vjenčanja za diskusiju o scenografiji, osvjetljenju i toku vaše priče.',3,NULL,NULL,NULL) ON CONFLICT (key) DO NOTHING;
INSERT INTO page_content (key,label,page,section,type,value_en,value_bs,sort_order,font_size,font_family,text_color) VALUES ('experience.addons.3.title','Addon 3: Naslov','services','addons','text','The Experience','Iskustvo',4,NULL,NULL,NULL) ON CONFLICT (key) DO NOTHING;
INSERT INTO page_content (key,label,page,section,type,value_en,value_bs,sort_order,font_size,font_family,text_color) VALUES ('experience.addons.3.desc','Addon 3: Opis','services','addons','textarea','We handle the details — from location scouting to seamless coordination — so you can remain fully present in the moment.','Brinemo o detaljima — od izviđanja lokacije do besprijekorne koordinacije.',5,NULL,NULL,NULL) ON CONFLICT (key) DO NOTHING;
INSERT INTO page_content (key,label,page,section,type,value_en,value_bs,sort_order,font_size,font_family,text_color) VALUES ('experience.addons.4.title','Addon 4: Naslov','services','addons','text','The Travel','Putovanje',6,NULL,NULL,NULL) ON CONFLICT (key) DO NOTHING;
