INSERT INTO page_content (key,label,page,section,type,value_en,value_bs,sort_order,font_size,font_family,text_color) VALUES ('about.title','Priča: Glavni naslov','about','story','text','Hi, we are Melisa & Aldin.','Zdravo, mi smo Melisa i Aldin.',0,NULL,NULL,NULL) ON CONFLICT (key) DO NOTHING;
INSERT INTO page_content (key,label,page,section,type,value_en,value_bs,sort_order,font_size,font_family,text_color) VALUES ('about.desc.1','Priča: Paragraf 1','about','story','textarea','Partners in life and lens. As photographers and filmmakers — and husband and wife — our work is a dialogue between editorial fashion and the moving image. Inspired by emotion, we take an intentional approach to your narrative.','Partneri u životu i iza objektiva. Kao fotografi i filmaši — i muž i žena — naš rad je dijalog između editorijalne mode i pokretne slike. Inspirisani emocijama, pristupamo vašoj priči s namjerom.',1,NULL,NULL,NULL) ON CONFLICT (key) DO NOTHING;
INSERT INTO page_content (key,label,page,section,type,value_en,value_bs,sort_order,font_size,font_family,text_color) VALUES ('about.desc.2','Priča: Paragraf 2','about','story','textarea','Just a bunch of ordinary people utterly in love with creating images of love for the past 8 years. And the next images we create could be of your love.','Samo dvoje zaljubljenih u stvaranje slika ljubavi proteklih 8 godina. Sljedeće slike koje stvorimo mogle bi biti vaše.',2,NULL,NULL,NULL) ON CONFLICT (key) DO NOTHING;
INSERT INTO page_content (key,label,page,section,type,value_en,value_bs,sort_order,font_size,font_family,text_color) VALUES ('about.desc.3','Priča: Paragraf 3 (citat)','about','story','textarea','We spend our days at other people''s weddings cracking half-witty jokes and trying to capture the quiet grandeur of love. We don''t just capture moments; we craft elevated imagery that resonates with the soul of your unique journey.','Provodimo dane na vjenčanjima zbijajući šale i pokušavajući uhvatiti tihu raskoš ljubavi. Mi ne bilježimo samo trenutke; mi stvaramo uzvišene slike koje rezonuju s dušom vašeg jedinstvenog putovanja.',3,NULL,NULL,NULL) ON CONFLICT (key) DO NOTHING;
INSERT INTO page_content (key,label,page,section,type,value_en,value_bs,sort_order,font_size,font_family,text_color) VALUES ('about.artists','Oznaka: Umjetnici','about','story','text','The Artists','Umjetnici',10,NULL,NULL,NULL) ON CONFLICT (key) DO NOTHING;
