INSERT INTO page_content (key,label,page,section,type,value_en,value_bs,sort_order,font_size,font_family,text_color) VALUES ('home.collections.weddings.desc','Kartica Vjenčanja: Opis','home','collections','textarea','Your special day, captured through its most beautiful moments.','Vaš poseban dan, zabilježen kroz najljepše trenutke.',3,NULL,NULL,NULL) ON CONFLICT (key) DO NOTHING;
INSERT INTO page_content (key,label,page,section,type,value_en,value_bs,sort_order,font_size,font_family,text_color) VALUES ('home.collections.studio.desc','Kartica Studio: Opis','home','collections','textarea','Timeless photographs in a perfectly composed setting.','Bezvremenske fotografije u savršenom ambijentu.',4,NULL,NULL,NULL) ON CONFLICT (key) DO NOTHING;
INSERT INTO page_content (key,label,page,section,type,value_en,value_bs,sort_order,font_size,font_family,text_color) VALUES ('home.collections.portraits.desc','Kartica Portreti: Opis','home','collections','textarea','Portraits that reveal your character and emotion.','Portreti koji otkrivaju vašu jedinstvenost i emociju.',5,NULL,NULL,NULL) ON CONFLICT (key) DO NOTHING;
