INSERT INTO page_content (key,label,page,section,type,value_en,value_bs,sort_order,font_size,font_family,text_color) VALUES ('about.facts.1.label','Sitnica 1: Naslov','about','facts','text','The first thing we ask','Prvo što pitamo',3,NULL,NULL,NULL) ON CONFLICT (key) DO NOTHING;
INSERT INTO page_content (key,label,page,section,type,value_en,value_bs,sort_order,font_size,font_family,text_color) VALUES ('about.facts.1.text','Sitnica 1: Tekst (prazno = sakriveno)','about','facts','textarea','How you met. The answer usually sets the tone for the whole day.','Kako ste se upoznali. Odgovor na to pitanje obično odredi ton cijelog dana.',4,NULL,NULL,NULL) ON CONFLICT (key) DO NOTHING;
INSERT INTO page_content (key,label,page,section,type,value_en,value_bs,sort_order,font_size,font_family,text_color) VALUES ('about.facts.2.label','Sitnica 2: Naslov','about','facts','text','Favourite part of the day','Najdraži dio dana',5,NULL,NULL,NULL) ON CONFLICT (key) DO NOTHING;
INSERT INTO page_content (key,label,page,section,type,value_en,value_bs,sort_order,font_size,font_family,text_color) VALUES ('about.facts.2.text','Sitnica 2: Tekst (prazno = sakriveno)','about','facts','textarea','The ten minutes before sunset, when everyone settles and the light turns gold.','Onih deset minuta pred zalazak, kada se svi smire a svjetlo postane zlatno.',6,NULL,NULL,NULL) ON CONFLICT (key) DO NOTHING;
INSERT INTO page_content (key,label,page,section,type,value_en,value_bs,sort_order,font_size,font_family,text_color) VALUES ('about.facts.3.label','Sitnica 3: Naslov','about','facts','text','Always in the bag','Uvijek u torbi',7,NULL,NULL,NULL) ON CONFLICT (key) DO NOTHING;
INSERT INTO page_content (key,label,page,section,type,value_en,value_bs,sort_order,font_size,font_family,text_color) VALUES ('about.facts.3.text','Sitnica 3: Tekst (prazno = sakriveno)','about','facts','textarea','Two cameras, spare batteries and a pack of tissues. The third one usually runs out first.','Dva fotoaparata, rezervne baterije i paket maramica. Treće se obično prvo potroši.',8,NULL,NULL,NULL) ON CONFLICT (key) DO NOTHING;
INSERT INTO page_content (key,label,page,section,type,value_en,value_bs,sort_order,font_size,font_family,text_color) VALUES ('about.facts.4.label','Sitnica 4: Naslov','about','facts','text','We never direct','Ne režiramo',9,NULL,NULL,NULL) ON CONFLICT (key) DO NOTHING;
INSERT INTO page_content (key,label,page,section,type,value_en,value_bs,sort_order,font_size,font_family,text_color) VALUES ('about.facts.4.text','Sitnica 4: Tekst (prazno = sakriveno)','about','facts','textarea','The laughter, the tears, and the looks you exchange when you think nobody is watching.','Smijeh, suze i poglede koje razmijenite kad mislite da niko ne gleda.',10,NULL,NULL,NULL) ON CONFLICT (key) DO NOTHING;
INSERT INTO page_content (key,label,page,section,type,value_en,value_bs,sort_order,font_size,font_family,text_color) VALUES ('about.facts.5.label','Sitnica 5: Naslov','about','facts','text','We love rain','Volimo kišu',11,NULL,NULL,NULL) ON CONFLICT (key) DO NOTHING;
INSERT INTO page_content (key,label,page,section,type,value_en,value_bs,sort_order,font_size,font_family,text_color) VALUES ('about.facts.5.text','Sitnica 5: Tekst (prazno = sakriveno)','about','facts','textarea','Honestly. Some of the best frames we have ever made happened under an umbrella.','Ozbiljno. Neke od najboljih fotografija koje smo napravili nastale su pod kišobranom.',12,NULL,NULL,NULL) ON CONFLICT (key) DO NOTHING;
INSERT INTO page_content (key,label,page,section,type,value_en,value_bs,sort_order,font_size,font_family,text_color) VALUES ('about.facts.6.label','Sitnica 6: Naslov','about','facts','text','After it all','Poslije svega',13,NULL,NULL,NULL) ON CONFLICT (key) DO NOTHING;
INSERT INTO page_content (key,label,page,section,type,value_en,value_bs,sort_order,font_size,font_family,text_color) VALUES ('about.facts.6.text','Sitnica 6: Tekst (prazno = sakriveno)','about','facts','textarea','We stay for the last song. We have never left before the end.','Ostanemo na zadnjoj pjesmi. Nikad nismo otišli prije kraja.',14,NULL,NULL,NULL) ON CONFLICT (key) DO NOTHING;
